SELECT *
FROM sector_fund_flow_snapshots
WHERE trade_date = #{tradeDate}
  AND snapshot_time = #{snapshotTime}
ORDER BY main_net_inflow DESC
LIMIT #{limit}

SELECT *
FROM sector_fund_flow_snapshots
WHERE trade_date = #{tradeDate}
  AND snapshot_time = #{snapshotTime}
ORDER BY main_net_inflow ASC
LIMIT #{limit}

SELECT sector_code, sector_name, snapshot_time, main_net_inflow FROM sector_fund_flow_snapshots WHERE trade_date = #{tradeDate}
AND sector_code IN
#{code}
ORDER BY sector_code, snapshot_time ASC
